      const attempt = () => url
        ? fetch(url).then((r) => (r.ok ? r.json() : Promise.reject(new Error("one-offs source HTTP " + r.status))))
        : Promise.resolve({});
      _oneOffsPromise = attempt()
        .catch(() => new Promise((res, rej) => setTimeout(() => attempt().then(res, rej), 1200)))
